/* Test stand-in for the external AES256 function.
 *
 * NOT AES and NOT secure: a cheap keyed mixing of the 16-octet block, good
 * enough to exercise CCSDSSDLSEncryptor (GCM/CTR only ever use the forward
 * block function). Every output octet depends on every key and input octet,
 * so tampering with a protected frame still breaks its MAC.
 *
 * set_aes_status selects the status the next calls report, so test_env can
 * exercise the encryptor's crypto-backend-failed path.
 */
#include "aes256_mock.h"

#include <stdint.h>
#include <string.h>

static asn1SccCrypto_Status g_status = Crypto_Status_ok;

static void mix(uint8_t s[16], const uint8_t key[32])
{
   for (unsigned r = 0; r < 4; r++) {
      for (unsigned i = 0; i < 16; i++) {
         uint8_t v = (uint8_t)(s[i] ^ key[i + 16 * (r & 1)]);
         v = (uint8_t)((v << 3) | (v >> 5));
         s[i] = (uint8_t)(v + s[(i + 15) % 16] + r);
      }
   }
}

void aes256_mock_startup(void)
{
}

void aes256_mock_PI_aes256_encrypt_block
      (const asn1SccAES256_Key *IN_key,
       const asn1SccAES_Block *IN_plaintext,
       asn1SccAES_Block *OUT_ciphertext,
       asn1SccCrypto_Status *OUT_status)

{
   *OUT_status = g_status;
   if (g_status != Crypto_Status_ok) {
      memset(OUT_ciphertext->arr, 0, sizeof(OUT_ciphertext->arr));
      return;
   }
   memcpy(OUT_ciphertext->arr, IN_plaintext->arr, 16);
   mix(OUT_ciphertext->arr, IN_key->arr);
}

void aes256_mock_PI_set_aes_status
      (const asn1SccCrypto_Status *IN_status)

{
   g_status = *IN_status;
}
